// ============================================================
// Node "2. Inhalte abrufen" - v4 mit verbesserter Block-Erkennung
// (ohne Zeichen-Limit - nimmt den kompletten Text)
// ============================================================
// Strategie:
//   1. Normaler Fetch                       (0 Credits)
//   2. ScraperAPI + render=true             (10 Credits)
//   3. ScraperAPI + render + ultra_premium  (75 Credits)
// ============================================================

// >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
// >>> SCRAPERAPI KEY                                        <<<
// >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
const SCRAPERAPI_KEY = '8db4aed44f43124148e4d07e1b24fcfd';
// >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

const params = $input.first().json;

// --- Robuste Input-Normalisierung ---
const normalizeArray = (input) => {
  if (input == null) return [];
  if (Array.isArray(input)) return input;
  if (typeof input === 'string') {
    const trimmed = input.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return parsed;
      if (typeof parsed === 'object' && parsed !== null) return [parsed];
      return [];
    } catch (e) {
      return [{ url: trimmed, starred: false }];
    }
  }
  if (typeof input === 'object') return [input];
  return [];
};

const normalizeUrlItem = (item) => {
  if (typeof item === 'string') {
    return { url: item, starred: false };
  }
  if (typeof item === 'object' && item !== null) {
    return {
      url: item.url || item.link || '',
      starred: item.starred === true
    };
  }
  return { url: '', starred: false };
};

const urls = normalizeArray(params.urls).map(normalizeUrlItem);
const texts = normalizeArray(params.texts);

// --- HTML zu Text (OHNE Laengen-Limit) ---
const htmlToText = (html) => {
  if (typeof html !== 'string') return String(html);
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<nav[\s\S]*?<\/nav>/gi, '')
    .replace(/<header[\s\S]*?<\/header>/gi, '')
    .replace(/<footer[\s\S]*?<\/footer>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#\d+;/g, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim();
};

// --- Block-Erkennung mit REGEX (toleranter) ---
const isBlocked = (text) => {
  if (!text || text.length < 100) return true;
  const lower = text.toLowerCase();

  // Regex-Muster fangen auch Variationen mit "bitte", "nun" etc.
  const regexPatterns = [
    /aktivier\w*\s+(sie\s+)?(bitte\s+)?(nun\s+)?javascript/,   // "Aktivieren Sie bitte JavaScript"
    /javascript\s+(ist\s+)?(nicht\s+)?(aktiviert|deaktiviert|disabled|required|erforderlich)/,
    /(please\s+)?enable\s+(js|javascript)/,
    /javascript\s+is\s+disabled/,
    /you\s+need\s+to\s+enable\s+javascript/,
    /kein\s+javascript\s+aktiviert/,                            // "kein JavaScript aktiviert"
    /javascript\s+muss\s+aktiviert/,
    /verify\s+(that\s+)?you\W+re?\s+not\s+a\s+robot/,
    /verify\s+that\s+you\s+are\s+not\s+a\s+robot/,
    /are\s+you\s+a\s+human/,
    /checking\s+your\s+browser/,
    /cf-browser-verification/,
    /access\s+denied/,
    /zugriff\s+verweigert/,
    /captcha/,
    /bot\s+detection/,
    /suspicious\s+activity/
  ];

  return regexPatterns.some(rx => rx.test(lower));
};

// --- Stufe 1: Standard Fetch ---
const standardFetch = async (url) => {
  const html = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    timeout: 15000,
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
      'Accept-Language': 'de-DE,de;q=0.9,en;q=0.8',
      'Accept-Encoding': 'gzip, deflate, br',
      'Upgrade-Insecure-Requests': '1',
      'Sec-Fetch-Dest': 'document',
      'Sec-Fetch-Mode': 'navigate',
      'Sec-Fetch-Site': 'none'
    }
  });
  return typeof html === 'string' ? html : String(html);
};

// --- Stufe 2: ScraperAPI Basic ---
const scraperApiBasic = async (url) => {
  const html = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.scraperapi.com/',
    timeout: 70000,
    qs: {
      api_key: SCRAPERAPI_KEY,
      url: url,
      render: 'true',
      country_code: 'de'
    }
  });
  return typeof html === 'string' ? html : String(html);
};

// --- Stufe 3: ScraperAPI Ultra ---
const scraperApiUltra = async (url) => {
  const html = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.scraperapi.com/',
    timeout: 90000,
    qs: {
      api_key: SCRAPERAPI_KEY,
      url: url,
      render: 'true',
      ultra_premium: 'true',
      country_code: 'de'
    }
  });
  return typeof html === 'string' ? html : String(html);
};

// --- Eskalations-Logik ---
const fetchUrl = async (urlObj) => {
  if (!urlObj.url || !urlObj.url.trim()) return null;
  const cleanUrl = urlObj.url.trim();
  const base = { url: cleanUrl, starred: urlObj.starred === true };

  let text = '';
  let method = 'standard';

  // Stufe 1
  try {
    const html = await standardFetch(cleanUrl);
    text = htmlToText(html);
  } catch (e) { /* zu Stufe 2 */ }

  if (!isBlocked(text)) {
    return { ...base, text, ok: true, method, length: text.length };
  }

  // Stufe 2
  try {
    const html = await scraperApiBasic(cleanUrl);
    text = htmlToText(html);
    method = 'scraperapi_basic';
  } catch (e) {
    return {
      ...base,
      text: '[ScraperAPI Basic fehlgeschlagen: ' + e.message + ']',
      ok: false,
      method: 'scraperapi_basic_failed'
    };
  }

  if (!isBlocked(text)) {
    return { ...base, text, ok: true, method, length: text.length };
  }

  // Stufe 3
  try {
    const html = await scraperApiUltra(cleanUrl);
    text = htmlToText(html);
    method = 'scraperapi_ultra';
  } catch (e) {
    return {
      ...base,
      text: '[ScraperAPI Ultra fehlgeschlagen: ' + e.message + ']',
      ok: false,
      method: 'scraperapi_ultra_failed'
    };
  }

  if (isBlocked(text)) {
    return {
      ...base,
      text: '[Seite konnte auch mit Ultra Premium nicht geladen werden - wahrscheinlich CAPTCHA]',
      ok: false,
      method: 'blocked'
    };
  }

  return { ...base, text, ok: true, method, length: text.length };
};

// --- Ausfuehrung ---
const results = await Promise.all(urls.map(fetchUrl));
const fetchedFromUrls = results.filter(r => r !== null);

const textItems = texts
  .filter(t => t && t.text && String(t.text).trim())
  .map(t => ({
    url: t.label || 'Direkt eingegeben',
    starred: t.starred === true,
    text: String(t.text),
    ok: true,
    method: 'direct',
    length: String(t.text).length
  }));

const fetched_urls = [...fetchedFromUrls, ...textItems];

return [{ json: { urls, texts, fetched_urls } }];

// =====================================================================
// "4a. Newsletter DOCX erstellen" (Variante A: Editorial)
// =====================================================================
// Erstellt einen Newsletter als .docx-Datei aus dem LLM-Output.
// Nutzt KEINE externen npm-Pakete - nur Node-Builtins (zlib, Buffer).
// Eine docx-Datei ist ein ZIP mit XML-Dateien. Beides kann Node selbst.
// =====================================================================

// ---------------------------------------------------------------------
// 1) JSON-PARSER (identisch zum bisherigen robusten Parser)
// ---------------------------------------------------------------------

function stripFences(raw) {
  if (typeof raw !== 'string') return '';
  return raw
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
}

function isolateJsonObject(s) {
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return s;
  return s.slice(start, end + 1);
}

function repairStringContents(s) {
  let out = '';
  let inString = false;
  let escape = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (escape) { out += ch; escape = false; continue; }
    if (ch === '\\') { out += ch; escape = true; continue; }
    if (ch === '"') {
      if (!inString) { inString = true; out += ch; }
      else {
        let j = i + 1;
        while (j < s.length && /\s/.test(s[j])) j++;
        const next = s[j];
        if (next === undefined || next === ',' || next === '}' || next === ']' || next === ':') {
          inString = false; out += ch;
        } else {
          out += '\\"';
        }
      }
      continue;
    }
    if (inString) {
      if (ch === '\n') { out += '\\n'; continue; }
      if (ch === '\r') { out += '\\r'; continue; }
      if (ch === '\t') { out += '\\t'; continue; }
    }
    out += ch;
  }
  return out;
}

function parseNewsletterJson(raw) {
  if (typeof raw !== 'string') {
    return { themenuebersicht: 'Kein LLM-Output erhalten.', articles: [] };
  }
  const s = isolateJsonObject(stripFences(raw));
  try { return JSON.parse(s); } catch (e) {}
  try {
    const s2 = s.replace(/,\s*}/g, '}').replace(/,\s*]/g, ']');
    return JSON.parse(s2);
  } catch (e) {}
  try {
    const repaired = repairStringContents(s)
      .replace(/,\s*}/g, '}').replace(/,\s*]/g, ']');
    return JSON.parse(repaired);
  } catch (e) {}
  try {
    const stripped = repairStringContents(s)
      .replace(/[\x00-\x1F\x7F]/g, ' ')
      .replace(/,\s*}/g, '}').replace(/,\s*]/g, ']');
    return JSON.parse(stripped);
  } catch (eFinal) {
    return {
      themenuebersicht: 'Newsletter konnte nicht generiert werden: ' + eFinal.message,
      articles: []
    };
  }
}

// ---------------------------------------------------------------------
// 2) XML-HELPERS
// ---------------------------------------------------------------------

function xmlEscape(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

// Wandelt \n in mehrere Paragraphen um
function textToRuns(text, runProps) {
  if (!text) return '';
  const lines = String(text).split(/\r?\n/);
  return lines.map(line =>
    `<w:r>${runProps}<w:t xml:space="preserve">${xmlEscape(line)}</w:t></w:r>`
  ).join('<w:br/>');
}

// Baut ein <w:p>-Paragraph mit Inhalt
function para(opts) {
  const {
    text = '',
    font = 'Georgia',
    size = 22,     // in halb-Punkt (22 = 11pt)
    color = '222222',
    bold = false,
    italics = false,
    allCaps = false,
    charSpacing = 0,     // in zwanzigstel-Punkt
    alignment = null,    // 'left' | 'center' | 'right' | 'both' (justify)
    spacingBefore = 0,
    spacingAfter = 0,
    spacingLine = 0,     // 0 = default (276 = 1.15 Zeilenabstand; 340 ~ 1.4)
    borderLeft = null,   // { color: 'RRGGBB', size: 18 (8tel-Pt), space: 16 (Pt) }
    borderTop = null,
    borderBottom = null,
    indentLeft = 0,      // in DXA
    indentRight = 0
  } = opts;

  // Element-Reihenfolge in pPr ist schema-gebunden:
  // pBdr, spacing, ind, jc, rPr
  const pPrParts = [];
  const borders = [];
  if (borderTop) borders.push(`<w:top w:val="single" w:sz="${borderTop.size}" w:space="${borderTop.space||1}" w:color="${borderTop.color}"/>`);
  if (borderBottom) borders.push(`<w:bottom w:val="single" w:sz="${borderBottom.size}" w:space="${borderBottom.space||1}" w:color="${borderBottom.color}"/>`);
  if (borderLeft) borders.push(`<w:left w:val="single" w:sz="${borderLeft.size}" w:space="${borderLeft.space||4}" w:color="${borderLeft.color}"/>`);
  if (borders.length) pPrParts.push(`<w:pBdr>${borders.join('')}</w:pBdr>`);
  if (spacingBefore || spacingAfter || spacingLine) {
    const atts = [];
    if (spacingBefore) atts.push(`w:before="${spacingBefore}"`);
    if (spacingAfter) atts.push(`w:after="${spacingAfter}"`);
    if (spacingLine) atts.push(`w:line="${spacingLine}" w:lineRule="auto"`);
    pPrParts.push(`<w:spacing ${atts.join(' ')}/>`);
  }
  if (indentLeft || indentRight) {
    const atts = [];
    if (indentLeft) atts.push(`w:left="${indentLeft}"`);
    if (indentRight) atts.push(`w:right="${indentRight}"`);
    pPrParts.push(`<w:ind ${atts.join(' ')}/>`);
  }
  if (alignment) pPrParts.push(`<w:jc w:val="${alignment}"/>`);

  const rPrParts = [];
  rPrParts.push(`<w:rFonts w:ascii="${font}" w:hAnsi="${font}" w:cs="${font}"/>`);
  if (bold) rPrParts.push('<w:b/>');
  if (italics) rPrParts.push('<w:i/>');
  if (allCaps) rPrParts.push('<w:caps/>');
  if (color) rPrParts.push(`<w:color w:val="${color}"/>`);
  rPrParts.push(`<w:sz w:val="${size}"/>`);
  rPrParts.push(`<w:szCs w:val="${size}"/>`);
  if (charSpacing) rPrParts.push(`<w:spacing w:val="${charSpacing}"/>`);
  const runProps = `<w:rPr>${rPrParts.join('')}</w:rPr>`;

  // Auch pPr darf rPr haben fuer Absatzmarken-Formatierung (fuer Borders/Abstaende wichtig)
  const pPr = pPrParts.length
    ? `<w:pPr>${pPrParts.join('')}<w:rPr>${rPrParts.join('')}</w:rPr></w:pPr>`
    : '';

  const runs = text
    ? textToRuns(text, runProps)
    : `<w:r>${runProps}<w:t xml:space="preserve"></w:t></w:r>`;

  return `<w:p>${pPr}${runs}</w:p>`;
}

// ---------------------------------------------------------------------
// 3) NEWSLETTER-LAYOUT (Variante A: Editorial)
// ---------------------------------------------------------------------

const DARKBLUE = "1A2744";
const BLUE = "1E3A8A";
const GRAY_META = "5A6A8A";
const GRAY_MUTED = "7A8A9A";
const TEXT_BLACK = "222222";

function buildDocumentXml(data) {
  const today = new Date();
  const months = ['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
  const dateStr = today.getDate() + '. ' + months[today.getMonth()] + ' ' + today.getFullYear();
  const ausgabeNr = today.toISOString().slice(0,10).replace(/-/g,'');

  const parts = [];

  // --- Haupttitel ---
  parts.push(para({
    text: 'Juristische Entwicklungen im Überblick',
    font: 'Georgia', size: 44, bold: true, color: DARKBLUE,
    spacingBefore: 400, spacingAfter: 120
  }));
  parts.push(para({
    text: 'Spezialausgabe · Quellenanalyse · ' + dateStr,
    font: 'Georgia', size: 22, italics: true, color: GRAY_META,
    spacingAfter: 480
  }));

  // --- Lead / Themenuebersicht mit linker blauer Linie ---
  parts.push(para({
    text: data.themenuebersicht || '',
    font: 'Georgia', size: 26, italics: true, color: DARKBLUE,
    spacingAfter: 480, spacingLine: 360,
    borderLeft: { color: BLUE, size: 18, space: 16 }
  }));

  // --- Artikel ---
  const articles = Array.isArray(data.articles) ? data.articles : [];
  articles.forEach((article, idx) => {
    // Trenner zwischen Artikeln
    if (idx > 0) {
      parts.push(para({
        text: '◆ ◆ ◆',
        alignment: 'center', font: 'Georgia', size: 16, color: BLUE,
        spacingBefore: 360, spacingAfter: 360
      }));
    }

    // Kicker "BEITRAG 1"
    parts.push(para({
      text: 'BEITRAG ' + (article.nummer || (idx + 1)),
      font: 'Arial', size: 16, bold: true, color: BLUE,
      charSpacing: 60, spacingAfter: 120
    }));

    // Titel
    parts.push(para({
      text: article.titel || '',
      font: 'Georgia', size: 36, bold: true, color: DARKBLUE,
      spacingAfter: 120
    }));

    // Meta (Quelle/Datum)
    parts.push(para({
      text: article.quelle_datum || '',
      font: 'Georgia', size: 20, italics: true, color: GRAY_META,
      spacingAfter: 280
    }));

    // Sections
    const section = (label, text) => {
      parts.push(para({
        text: label,
        font: 'Arial', size: 18, bold: true, color: BLUE,
        charSpacing: 40, allCaps: true,
        spacingBefore: 240, spacingAfter: 80
      }));
      parts.push(para({
        text: text || '',
        font: 'Georgia', size: 22, color: TEXT_BLACK,
        alignment: 'both',
        spacingAfter: 120, spacingLine: 340
      }));
    };
    section('Sachverhalt und Hintergrund', article.sachverhalt);
    section('Entscheidung und Regelung', article.entscheidung_regelung);
    section('Praktische Bedeutung', article.praktische_bedeutung);
    section('Relevante Details', article.relevante_details);
  });

  if (!articles.length) {
    parts.push(para({
      text: 'Keine Artikel im Input gefunden.',
      font: 'Georgia', size: 22, color: TEXT_BLACK
    }));
  }

  // --- Disclaimer ---
  parts.push(para({
    text: '',
    spacingBefore: 600,
    borderTop: { color: 'CCCCCC', size: 6, space: 12 }
  }));
  parts.push(para({
    text: 'Dieser Newsletter wurde automatisch erstellt. Alle Inhalte dienen ausschliesslich der allgemeinen Information und stellen keine Rechtsberatung dar.',
    font: 'Georgia', size: 16, italics: true, color: GRAY_MUTED,
    spacingBefore: 120
  }));

  // --- Section mit Header/Footer ---
  const header = buildHeaderXml(dateStr);
  const footer = buildFooterXml(ausgabeNr);

  const sectPr = `
    <w:sectPr>
      <w:headerReference w:type="default" r:id="rId10"/>
      <w:footerReference w:type="default" r:id="rId11"/>
      <w:pgSz w:w="11906" w:h="16838"/>
      <w:pgMar w:top="1600" w:right="1800" w:bottom="1600" w:left="1800" w:header="720" w:footer="720" w:gutter="0"/>
      <w:cols w:space="708"/>
      <w:docGrid w:linePitch="360"/>
    </w:sectPr>`;

  const body = `
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
            xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <w:body>
    ${parts.join('\n')}
    ${sectPr}
  </w:body>
</w:document>`;

  return { body, header, footer };
}

function buildHeaderXml(dateStr) {
  // Kopfzeile mit Marke links, Datum rechts, Linie drunter
  const headerPara = `
    <w:p>
      <w:pPr>
        <w:tabs>
          <w:tab w:val="right" w:pos="8306"/>
        </w:tabs>
        <w:spacing w:after="80"/>
      </w:pPr>
      <w:r>
        <w:rPr>
          <w:rFonts w:ascii="Georgia" w:hAnsi="Georgia"/>
          <w:b/>
          <w:color w:val="${DARKBLUE}"/>
          <w:spacing w:val="40"/>
          <w:sz w:val="20"/>
        </w:rPr>
        <w:t>RECHTSNEWS</w:t>
      </w:r>
      <w:r>
        <w:rPr><w:rFonts w:ascii="Georgia" w:hAnsi="Georgia"/></w:rPr>
        <w:tab/>
      </w:r>
      <w:r>
        <w:rPr>
          <w:rFonts w:ascii="Georgia" w:hAnsi="Georgia"/>
          <w:color w:val="${GRAY_META}"/>
          <w:sz w:val="18"/>
        </w:rPr>
        <w:t xml:space="preserve">${xmlEscape(dateStr)}</w:t>
      </w:r>
    </w:p>
    <w:p>
      <w:pPr>
        <w:pBdr>
          <w:bottom w:val="single" w:sz="6" w:space="1" w:color="${DARKBLUE}"/>
        </w:pBdr>
      </w:pPr>
    </w:p>`;

  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:hdr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  ${headerPara}
</w:hdr>`;
}

function buildFooterXml(ausgabeNr) {
  // Fusszeile mit Seitenzahl zentriert
  const footerPara = `
    <w:p>
      <w:pPr>
        <w:jc w:val="center"/>
      </w:pPr>
      <w:r>
        <w:rPr>
          <w:rFonts w:ascii="Georgia" w:hAnsi="Georgia"/>
          <w:color w:val="${GRAY_MUTED}"/>
          <w:sz w:val="16"/>
        </w:rPr>
        <w:t xml:space="preserve">Juristischer Newsletter · Ausgabe ${xmlEscape(ausgabeNr)} · Seite </w:t>
      </w:r>
      <w:r>
        <w:rPr>
          <w:rFonts w:ascii="Georgia" w:hAnsi="Georgia"/>
          <w:color w:val="${GRAY_MUTED}"/>
          <w:sz w:val="16"/>
        </w:rPr>
        <w:fldChar w:fldCharType="begin"/>
      </w:r>
      <w:r>
        <w:rPr>
          <w:rFonts w:ascii="Georgia" w:hAnsi="Georgia"/>
          <w:color w:val="${GRAY_MUTED}"/>
          <w:sz w:val="16"/>
        </w:rPr>
        <w:instrText xml:space="preserve">PAGE</w:instrText>
      </w:r>
      <w:r><w:fldChar w:fldCharType="end"/></w:r>
    </w:p>`;

  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:ftr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  ${footerPara}
</w:ftr>`;
}

// ---------------------------------------------------------------------
// 4) ZIP-WRITER (ohne externe Pakete, nur zlib)
// ---------------------------------------------------------------------
// Eine .docx-Datei ist ein ZIP-Archiv. Wir bauen das ZIP von Hand
// nach der PKZip-Spezifikation.

function crc32(buf) {
  let table = crc32.table;
  if (!table) {
    table = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      table[i] = c >>> 0;
    }
    crc32.table = table;
  }
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) {
    crc = (crc >>> 8) ^ table[(crc ^ buf[i]) & 0xFF];
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function dosDateTime(d) {
  const dosTime =
    ((d.getHours() & 0x1F) << 11) |
    ((d.getMinutes() & 0x3F) << 5) |
    ((Math.floor(d.getSeconds() / 2)) & 0x1F);
  const dosDate =
    (((d.getFullYear() - 1980) & 0x7F) << 9) |
    (((d.getMonth() + 1) & 0x0F) << 5) |
    (d.getDate() & 0x1F);
  return { dosTime, dosDate };
}

function buildZip(files) {
  // files = [{ name, data: Buffer }]
  const now = new Date();
  const { dosTime, dosDate } = dosDateTime(now);
  const localChunks = [];
  const centralChunks = [];
  let offset = 0;

  for (const f of files) {
    const nameBuf = Buffer.from(f.name, 'utf-8');
    const raw = Buffer.isBuffer(f.data) ? f.data : Buffer.from(f.data, 'utf-8');
    const stored = raw;
    const crc = crc32(raw);

    // Local file header
    const local = Buffer.alloc(30 + nameBuf.length);
    let p = 0;
    local.writeUInt32LE(0x04034b50, p); p += 4;         // signature
    local.writeUInt16LE(20, p); p += 2;                 // version needed
    local.writeUInt16LE(0x0800, p); p += 2;             // general purpose flag (UTF-8)
    local.writeUInt16LE(0, p); p += 2;                  // method: store (no compression)
    local.writeUInt16LE(dosTime, p); p += 2;
    local.writeUInt16LE(dosDate, p); p += 2;
    local.writeUInt32LE(crc, p); p += 4;
    local.writeUInt32LE(stored.length, p); p += 4;
    local.writeUInt32LE(raw.length, p); p += 4;
    local.writeUInt16LE(nameBuf.length, p); p += 2;
    local.writeUInt16LE(0, p); p += 2;                  // extra length
    nameBuf.copy(local, p);

    localChunks.push(local);
    localChunks.push(stored);

    // Central directory entry
    const central = Buffer.alloc(46 + nameBuf.length);
    p = 0;
    central.writeUInt32LE(0x02014b50, p); p += 4;       // signature
    central.writeUInt16LE(20, p); p += 2;               // version made by
    central.writeUInt16LE(20, p); p += 2;               // version needed
    central.writeUInt16LE(0x0800, p); p += 2;           // general purpose
    central.writeUInt16LE(0, p); p += 2;                // method: store (no compression)
    central.writeUInt16LE(dosTime, p); p += 2;
    central.writeUInt16LE(dosDate, p); p += 2;
    central.writeUInt32LE(crc, p); p += 4;
    central.writeUInt32LE(stored.length, p); p += 4;
    central.writeUInt32LE(raw.length, p); p += 4;
    central.writeUInt16LE(nameBuf.length, p); p += 2;
    central.writeUInt16LE(0, p); p += 2;                // extra length
    central.writeUInt16LE(0, p); p += 2;                // comment length
    central.writeUInt16LE(0, p); p += 2;                // disk number
    central.writeUInt16LE(0, p); p += 2;                // internal attrs
    central.writeUInt32LE(0, p); p += 4;                // external attrs
    central.writeUInt32LE(offset, p); p += 4;           // local header offset
    nameBuf.copy(central, p);

    centralChunks.push(central);

    offset += local.length + stored.length;
  }

  const centralDir = Buffer.concat(centralChunks);
  const centralSize = centralDir.length;
  const centralOffset = offset;

  // End of central directory
  const eocd = Buffer.alloc(22);
  let p = 0;
  eocd.writeUInt32LE(0x06054b50, p); p += 4;
  eocd.writeUInt16LE(0, p); p += 2;                     // disk
  eocd.writeUInt16LE(0, p); p += 2;                     // disk of central dir
  eocd.writeUInt16LE(files.length, p); p += 2;
  eocd.writeUInt16LE(files.length, p); p += 2;
  eocd.writeUInt32LE(centralSize, p); p += 4;
  eocd.writeUInt32LE(centralOffset, p); p += 4;
  eocd.writeUInt16LE(0, p); p += 2;                     // comment length

  return Buffer.concat([...localChunks, centralDir, eocd]);
}

// ---------------------------------------------------------------------
// 5) DOCX ZUSAMMENBAUEN (alle noetigen Begleitdateien)
// ---------------------------------------------------------------------

function buildDocx(data) {
  const { body, header, footer } = buildDocumentXml(data);

  const contentTypes = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
  <Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>
  <Override PartName="/word/header1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/>
  <Override PartName="/word/footer1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/>
</Types>`;

  const rels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>`;

  const documentRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
  <Relationship Id="rId10" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/header" Target="header1.xml"/>
  <Relationship Id="rId11" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/>
</Relationships>`;

  const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:docDefaults>
    <w:rPrDefault>
      <w:rPr>
        <w:rFonts w:ascii="Georgia" w:hAnsi="Georgia" w:cs="Georgia"/>
        <w:sz w:val="22"/>
        <w:szCs w:val="22"/>
      </w:rPr>
    </w:rPrDefault>
    <w:pPrDefault>
      <w:pPr>
        <w:spacing w:after="120" w:line="300" w:lineRule="auto"/>
      </w:pPr>
    </w:pPrDefault>
  </w:docDefaults>
  <w:style w:type="paragraph" w:default="1" w:styleId="Normal">
    <w:name w:val="Normal"/>
    <w:qFormat/>
  </w:style>
</w:styles>`;

  const documentXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
${body}`;

  const files = [
    { name: '[Content_Types].xml', data: contentTypes },
    { name: '_rels/.rels', data: rels },
    { name: 'word/_rels/document.xml.rels', data: documentRels },
    { name: 'word/document.xml', data: documentXml },
    { name: 'word/styles.xml', data: styles },
    { name: 'word/header1.xml', data: header },
    { name: 'word/footer1.xml', data: footer }
  ];

  return buildZip(files);
}

