const input = $input.first().json;

// 1) Richtiges Quellfeld holen
const llmRaw =
  input?.choices?.[0]?.message?.content ??
  input?.output ??
  input?.text ??
  input?.content ??
  '';

// 2) Zielobjekt
let postData = { post_text: '', hashtags: [] };

// 3) Robust JSON parser
function tryParse(str) {
  if (typeof str !== 'string') return null;

  let s = str.trim();

  // Markdown-Fences entfernen
  s = s.replace(/^```json\s*/i, '').replace(/^```\s*/g, '').replace(/```$/g, '').trim();

  // Falls der Text noch "drumherum" enthält: erstes JSON-Objekt isolieren
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  s = s.slice(start, end + 1);

  // 1. Versuch: direkt parsen
  try {
    return JSON.parse(s);
  } catch (e) {}

  // 2. Versuch: Zeilenumbrüche in Strings escapen
  try {
    const fixed = s
      .replace(/\r/g, '\\r')
      .replace(/\n/g, '\\n');
    return JSON.parse(fixed);
  } catch (e) {}

  // 3. Versuch: Kontrollzeichen entfernen und trailing commas bereinigen
  try {
    const stripped = s
      .replace(/[\x00-\x1F\x7F]/g, ' ')
      .replace(/,\s*}/g, '}')
      .replace(/,\s*]/g, ']');
    return JSON.parse(stripped);
  } catch (e) {}

  return null;
}

const parsed = tryParse(llmRaw);

if (parsed && typeof parsed === 'object' && parsed.post_text) {
  postData = parsed;
} else {
  // Fallback: Regex-Extraktion
  const textMatch = String(llmRaw).match(/"post_text"\s*:\s*"((?:[^"\\]|\\[\s\S])*)"/);
  const hashMatch = String(llmRaw).match(/"hashtags"\s*:\s*\[([^\]]*)\]/);

  if (textMatch) {
    postData.post_text = textMatch[1]
      .replace(/\\n/g, '\n')
      .replace(/\\"/g, '"')
      .replace(/\\\\/g, '\\');
  } else {
    postData.post_text = 'LinkedIn-Post konnte nicht generiert werden.';
  }

  if (hashMatch) {
    postData.hashtags = (hashMatch[1].match(/"([^"]+)"/g) || []).map(h => h.replace(/"/g, ''));
  }
}

// 4) Text bereinigen
const cleanText = (postData.post_text || '')
  .replace(/^\* /gm, '- ')
  .replace(/\[Link[^\]]*\]/gi, '')
  .replace(/\[[^\]]{1,60}\]/g, '')
  .trim();

const hashtags = Array.isArray(postData.hashtags)
  ? postData.hashtags.map(h => h.startsWith('#') ? h : `#${h}`)
  : [];

const fullText = cleanText + (hashtags.length ? '\n\n' + hashtags.join('  ') : '');

// 5) Output
return [{
  json: {
    linkedin_post_text: cleanText,
    linkedin_hashtags: postData.hashtags || [],
    linkedin_char_count: fullText.length
  }
}];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const heute = new Date().toISOString().slice(0, 10);

return [{
  json: {
    newsletter_base64: buf.toString('base64'),
    newsletter_filename: `newsletter_url_${heute}.docx`,
    newsletter_mimetype: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  }
}];

const items = $input.all();
let result = { status: 'success' };
for (const item of items) {
  Object.assign(result, item.json);
}
return [{ json: result }];

